// Feedback 作业平台：路径常量与运行数据目录。
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));

export const ROOT = path.resolve(HERE, "..");
export const PUBLIC_DIR = path.join(ROOT, "public");
// 运行数据目录默认在安装目录下的 .feedback-data。设置 FEEDBACK_DATA_DIR 可以把设置与任务状态固定到
// 其他地方：解压到新目录后指回同一个数据目录即可继续用原来的设置，不用重新配置。
export const DATA_DIR = process.env.FEEDBACK_DATA_DIR
  ? path.resolve(process.env.FEEDBACK_DATA_DIR)
  : path.join(ROOT, ".feedback-data");
export const QUEUE_DIR = path.join(DATA_DIR, "queue");
export const JOBS_DIR = path.join(DATA_DIR, "jobs");
export const CANCEL_DIR = path.join(DATA_DIR, "cancel");
export const STAGE_DIR = path.join(DATA_DIR, "artifacts");
// 本机运行脚本目录：Windows 使用 .cmd，macOS 使用 .command。
export const ARTIFACT_STAGE_DIR = path.join(STAGE_DIR, "scripts");
// 批量写入用的请求正文：字段值里可能有几千字的题目原文，命令行放不下，统一走文件。
export const PAYLOAD_DIR = path.join(DATA_DIR, "payloads");
export const ATTACHMENT_DIR = path.join(DATA_DIR, "attachments");
